export function LanguageProvider({ language, children }) {
  return <languageContext.Provider value={language}>{children}</languageContext.Provider>;
}

export function useTranslation() {
  const language = useContext(languageContext);
  const locale = language === 'en' ? 'en-GB' : language === 'it' ? 'it-IT' : 'fr-FR';
  const translateText = (text) => messages[language]?.[text] || apiErrors[language]?.[text] || dateMessages[language]?.[text] || text;
  return { language, locale, translateText };
}

export function translate(text, language) {
  return messages[language]?.[text] || apiErrors[language]?.[text] || dateMessages[language]?.[text] || text;
}